// sl — Slovenščina (esloveno).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// NÃO É O CROATA. São vizinhas e eslavas do sul, mas o esloveno tem outra ortografia (č, š, ž e nada de
// ć ou đ), outro vocabulário ("shrani", "zdaj", "še", "gumb") e uma coisa que nenhuma outra do Syden tem:
// o NÚMERO DUAL.
//
// TOM: **ti**, e não *vi* — como no tcheco, no eslovaco e no croata do Syden. O *vikanje* é o das
// repartições e de boa parte do software de escritório; entre amigos e em apps de conversa e de jogo, é ti.
//
// GÊNERO: ESTÁ NO PASSADO E NO ADJETIVO, como em todo eslavo: pozabil (homem) / pozabila (mulher),
// prepričan / prepričana, utišan / utišana. Saída igual à do cs.ts: PRESENTE e FUTURO são neutros
// (imaš, lahko, izgubiš), o IMPESSOAL também (poslano, izbrisano, shranjeno), e onde o adjetivo diria o
// sexo vai advérbio ("Res izbrisati…?") ou o adjetivo passa para uma COISA ("Mikrofon imaš utišan"). A
// saudação é *Dobrodošli*, a forma que todo cartaz esloveno usa e que não diz o sexo de ninguém — a
// alternativa seria escolher entre dobrodošel e dobrodošla. Os nomes de cargo (Skrbnik, Lastnik, Član)
// ficam no masculino genérico, como em toda interface eslovena: são rótulos de papel.
//
// PLURAL: QUATRO formas, por causa do dual — 1 sporočilo, 2 sporočili, 3–4 sporočila, 5+ sporočil. O
// t() não escolhe forma nenhuma, então vale a saída do polonês e do tcheco: rótulo e número,
// "Sporočila: {n}". Onde o número é fixo na chave ("15 membros"), vai a forma certa para ele.
//
// DECLINAÇÃO: o esloveno declina nome próprio, então {nome} nunca vem colado à preposição — vem depois de
// um substantivo que leva o caso ("v skupnosti {comunidade}") ou depois de dois-pontos.
//
// NÚMEROS: `Intl.NumberFormat('sl')` devolve `1.234.567` — latinos, com ponto.
//
// O DETECTOR DO TESTE DE IDIOMAS: latino — vai o das chaves.
//
// VOCABULÁRIO, decidido uma vez: comunidade = skupnost, canal = kanal, sala de voz = glasovna soba,
// chamada = klic, conversa = pogovor, mensagem = sporočilo, senha = geslo, lixeira = koš, tópico = nit,
// conta = račun, administrador = skrbnik, dono = lastnik, cargo = vloga, convite = povabilo, perfil =
// profil, transmissão = prenos, tela = zaslon, membro = član, pacote = paket, enquete = anketa, denúncia
// = prijava, vila = vas, guarda-roupa = garderoba, cutucada = dregljaj, recado (da tela de boas-vindas e
// do aviso) = obvestilo.
//
// SOM E VOZ SÃO DUAS PALAVRAS: glas é a voz, zvok é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = pečat (o da comunidade), insígnia = značka (a da pessoa).

