  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden v kanalu objavi nagrado, in kdor želi sodelovati, se odzove z 🎉. Ob določenem času izžreba med odzivi in objavi rezultat.',
