  'Mês': 'Mesec',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Na rojstni dan tistega, ki je vpisal datum, Syden objavi voščilo v izbranem kanalu. Namesto imena uporabi {pessoa}.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Samo dan in mesec, nikoli leto. Skupnosti, ki objavljajo rojstne dneve, voščijo na ta dan. Neobvezno, in lahko izbrišeš kadar koli.',
