  'Uma vez': 'Enkrat',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Nekdo napiše ukaz na začetek sporočila, na primer !regras, in Syden v kanalu odgovori z besedilom, ki ga vneseš. Uporabi {pessoa} za ime tistega, ki je vprašal, in {comunidade} za ime skupnosti.',
