  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Pravila, ki jih Syden uveljavi sam, preden se sporočilo pokaže. Za skrbnike ne veljajo. Blokirano sporočilo se z razlogom vrne avtorju in ga nihče drug ne vidi.',
