  'Lobisomem': 'Volkodlak',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Ponoči z drugimi volkodlaki izberi, koga napasti. Podnevi ne dovoli, da bi kdo posumil.',
  'Vidente': 'Orakelj',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Ponoči odkrij, ali je kdo volkodlak. Podnevi povej, če se ti zdi vredno tveganja.',
  'Anjo': 'Angel',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Ponoči izberi nekoga za zaščito. Če volkodlaki napadejo to osebo, preživi.',
  'Da vila': 'Iz vasi',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Ponoči spi. Podnevi odkrij, kdo so volkodlaki, in glasuj, da jih izločite iz igre.',
