  'Os lobisomens venceram!': 'Volkodlaki so zmagali!',
  'Noite {n}. A vila dorme.': 'Noč {n}. Vas spi.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Volkodlaki so ponoči napadli: {nome}.',
  'Ninguém morreu esta noite.': 'Ta noč je minila brez žrtev.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Dan {n}. Pogovorite se in glasujte, kdo je po vašem volkodlak.',
  'A vila tirou {nome} do jogo.': 'Vas je izločila iz igre: {nome}.',
  'Empate: ninguém sai hoje.': 'Neodločeno: danes nihče ne izpade.',
  'Clique em quem os lobisomens vão atacar.': 'Izberi, koga bodo volkodlaki napadli.',
  'Você já usou a sua visão esta noite.': 'Vizija za to noč je že porabljena.',
  'Clique em alguém para descobrir se é lobisomem.': 'Klikni nekoga in odkrij, ali je volkodlak.',
  'Clique em quem você quer proteger esta noite.': 'Izberi, koga želiš to noč zaščititi.',
  'Durma. Os outros papéis estão agindo.': 'Spi. Druge vloge so na delu.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Zunaj igre si. Zdaj samo gledaš — nič ne izdaj!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Izberi, koga želiš izločiti iz igre. Kdor ima največ glasov, izpade; pri neodločenem nihče.',
