  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}): odstranjeno iz Sydena, ker {quem} trdi, da ima pravice. Če imaš dovoljenje za objavo, odgovori tukaj in pojasni: tvoj odgovor bo upoštevan. Dokler to ni jasno, ostane odstranjeno. Kako to deluje, pojasnjujejo pogoji v razdelku 4: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}»: odstranjeno.',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'Skupaj s tem odstranjene kopije iste datoteke: {n}.',
