  'Direito autoral': 'Avtorske pravice',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'Kdor ima pravice, piše na direitos@syden.chat, kaj je to in kje je. Poišči po imenu, odstrani, in oseba, ki je to naložila, dobi obvestilo v pogovoru s tabo, kjer lahko ugovarja.',
