  'Tickets': 'Zahtevki',
  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'Kdor mora govoriti z upravo, odpre zahtevek na začetku skupnosti in napiše zadevo. Ta postane zasebni skupinski pogovor med to osebo in upravitelji ter se pojavi na vašem seznamu pogovorov.',
