  'Ligue a sua conta do Google, Discord, GitHub ou Steam para entrar no Syden por lá, sem digitar senha. Dá para ligar mais de um, e todos levam a esta mesma conta.': 'Poveži svoj račun Google, Discord, GitHub ali Steam in se prek njega prijavljaj v Syden, brez gesla. Povežeš lahko več računov in vsi vodijo do tega istega računa.',
