  'Folhas grandes para encher um canto de verde.': 'Veliki listi, ki ozelenijo kot.',
  'Pequena e cheia, num cesto de palha.': 'Majhna in košata, v slamnati košari.',
  'Mostra quem está transmitindo agora.': 'Pokaže, kdo trenutno pretaka.',
  'Cabe a turma inteira na frente da TV.': 'Pred televizijo je prostora za vso druščino.',
  'Baixinha, perto do sofá, para a pipoca e o refrigerante.': 'Nizka, ob kavču, za kokice in sok.',
  'Abre os mini-games para jogar com a turma.': 'Odpre mini igre za igranje z druščino.',
  'Cada prateleira guarda os canais da comunidade.': 'Vsaka polica hrani kanale skupnosti.',
  'Onde o coelho do recado espera quem chega.': 'Tu zajček s sporočilom čaka na prišleke.',
  'Alta, para sentar no balcão e conversar.': 'Visok, za sedenje ob pultu in klepet.',
  'Uma máquina de música antiga, com luzes que acendem à noite.': 'Star glasbeni avtomat z lučkami, ki ponoči zasvetijo.',
  'Com caixa de som, pronto para o karaokê.': 'Z zvočnikom, pripravljen za karaoke.',
  'Redonda, para cartas, tabuleiro e conversa.': 'Okrogla, za karte, družabne igre in klepet.',
  'De madeira, com o assento estofado.': 'Lesen, s podloženim sedežem.',
  'Suco, refrigerante e água sempre gelados.': 'Sok, gazirana pijača in voda, vedno hladni.',
  'A cozinha da turma. O botão direito acende e apaga o fogão.': 'Kuhinja druščine. Desni gumb prižge in ugasne štedilnik.',
  'Um pufe enorme, para afundar e ficar.': 'Ogromna sedalna vreča, v katero se ugrezneš in ostaneš.',
  'Pendurado no gancho, esperando a próxima call.': 'Visijo na kljukici in čakajo na naslednji klic.',
  'Fotos dos amigos presas num varal.': 'Fotografije prijateljev na vrvici.',
  'Recados e ideias presos com alfinete.': 'Sporočila in ideje, pripeti z bucikami.',
  'Livros, uma plantinha e um vaso.': 'Knjige, rastlinica in vaza.',
  'Um pôr do sol sobre os campos.': 'Sončni zahod nad polji.',
  'Xícaras, potes e garrafas de suco.': 'Skodelice, kozarci in steklenice soka.',
  'Potes de biscoito e pipoca para dividir.': 'Kozarci s piškoti in kokicami za deljenje.',
  'As taças das vitórias da turma.': 'Pokali zmag druščine.',
  'Um coelho de neon que brilha no escuro.': 'Neonski zajček, ki sveti v temi.',
  'Um relógio de madeira para ninguém perder a hora.': 'Lesena ura, da nihče ne zamudi.',
  'Para quem quiser puxar uma música.': 'Za vsakogar, ki bi rad zaigral kakšno pesem.',
  'Dá no banheiro. Bata antes de entrar.': 'Vodijo v kopalnico. Potrkaj, preden vstopiš.',
  'O cartaz do karaokê, em três versões: palco, neon e fogo.': 'Plakat za karaoke v treh različicah: oder, neon in ogenj.',
  'Dois coelhos, um café e a fofoca do dia.': 'Dva zajčka, kava in tračevi dneva.',
  'Café quentinho, ainda soltando fumaça.': 'Vroča kava, še se kadi.',
  'Suco de laranja com canudinho.': 'Pomarančni sok s slamico.',
  'Uma lata gelada.': 'Hladna pločevinka gazirane pijače.',
  'Uma suculenta pequena, que quase não pede água.': 'Majhen sukulent, ki skoraj ne potrebuje vode.',
  'Uma pilha de livros para ler depois.': 'Kup knjig za pozneje.',
  'O console da turma, com o controle ao lado.': 'Konzola druščine, s krmilnikom ob strani.',
  'Um balde de pipoca para ver a transmissão.': 'Vedro kokic za gledanje prenosa.',
  'Uma lembrança num porta-retrato.': 'Spomin v okvirju.',
  'Uma pizza inteira para dividir.': 'Cela pica za deljenje.',
  'Um pacote de salgadinho aberto.': 'Odprta vrečka čipsa.',
