  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Osem lukenj v 3D, s klančinami, gradom in mlinom na veter, vsi igrajo isto hkrati. Povleci za merjenje in moč ter spusti. Zmaga, kdor ima skupaj najmanj udarcev.',
  'Ver o buraco de cima': 'Poglej luknjo od zgoraj',
  'Fora da pista! Mais uma tacada.': 'Izven proge! Še en udarec.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Povleci vstran za merjenje in navzdol za moč ter spusti. S tipkovnico: puščice merijo, pridržana preslednica pa da moč.',
  'Futebol dos coelhos': 'Zajčji nogomet',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Nogomet na malem igrišču, od zgoraj. Dotakni se žoge, da jo vodiš, pridrži preslednico za močnejši strel in podaj s tipko X. V sobi ekipe dopolnijo roboti.',
