  'Caça às pragas da horta': 'Lov na škodljivce na vrtu',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Vrane in kobilice napadajo vrt. Meri in klikni, da jih zadeneš, preden pobegnejo: strelivo je prešteto, vsak val pa pride hitreje. Zmaga tisti, ki zbere največ točk.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Meri in klikni na škodljivce, preden pobegnejo. Vsak strel porabi en korenček.',
