  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Premalo ljudi: partija se je končala pred koncem, brez pokalov.',
  'Saiu antes do fim': 'Odhod pred koncem',
  'Jogar o dado': 'Vrzi kocko',
  '{nome} comprou a cenoura dourada!': '{nome} kupi zlati korenček!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Kupiš zlati korenček za {preco} korenčkov?',
  'Comprar': 'Kupi',
  '{nome} chegou à cenoura dourada.': '{nome} pride do zlatega korenčka.',
  'Quantas rodadas?': 'Koliko krogov?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Zajci branijo vrt pred lisicami, vranami in jazbecem. Hodite skupaj, udarjajte v kombu in pazite drug na drugega: od 1 do 4 ljudi.',
  'Pulo do coelho': 'Zajčji skok',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Dirka po ploščadih: teci, skači in ne padi. Solo proti času in duhovom prijateljev; s skupino v živo, na eni stopnji ali na vseh treh.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Zamenjaj dve sosednji zelenjavi, da zbereš tri ali več enakih. Kup raste brez prestanka: ne pusti, da doseže vrh. S skupino verige in kombi pošiljajo zaboje drugim.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Šest lukenj minigolfa, vsi igrajo isto hkrati. Povleci žogico nazaj in spusti, da udariš. Zmaga tisti, ki ima skupaj najmanj udarcev.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Vsak na svoji potezi vrže kocko in gre po vrtu. Zbiraj korenčke, da kupiš zlati korenček, po vsakem krogu pa skupina igra mini igro. Zmaga tisti, ki ima največ zlatih korenčkov.',
