  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Potuj po prestolnicah Brazilije, kupuj mesta in pobiraj najemnino od tistih, ki se ustavijo na njih. S celo regijo lahko gradiš stavbe. Menjaj, licitiraj na dražbah in ne ostani brez denarja.',
