  'No app do Syden, o recorte funciona com qualquer fundo.': 'V aplikaciji Syden odstranjevanje deluje s katerim koli ozadjem.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'Odstranjevanje z modelom ni uspelo, zato je bilo uporabljeno preprosto.',
  'Mandar figurinha': 'Pošlji nalepko',
  'Tirar figurinha': 'Odstrani nalepko',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'Ustvarjaj nalepke iz svojih slik ali shrani tiste, ki jih dobiš v pogovoru.',
  'Dominó': 'Domine',
  'Truco': 'Truco',
  'Damas': 'Dama',
  'Batalha naval': 'Potapljanje ladjic',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Klasične domine za 2 do 4 igralce (pri štirih v parih). Ploščice polagaj na konca, in kdor se jih prvi znebi, dobi točke iz rok drugih.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco iz São Paula, z obrnjeno karto in aduti, v dvoje ali v dveh parih. Napovej truco, dvigni na šest, devet in dvanajst ali zbeži. Zmaga, kdor zbere 12 točk.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brazilska dama: jemanje je obvezno, naprej in nazaj, dama pa se premika po celi diagonali. Soba gleda.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Vsak skrije svoje ladjevje in strelja v morje drugega. Če zadeneš, streljaš znova. Zmaga, kdor prvi potopi celotno ladjevje. Soba gleda.',
