  Xadrez: 'Šah',
  'Uma partida de xadrez inteira, com todas as regras. Quem abre fica com as brancas. A sala assiste.': 'Cela šahovska partija z vsemi pravili. Kdor začne, igra z belimi. Soba gleda.',
