  Dama: 'Dama',
  Torre: 'Trdnjava',
  Bispo: 'Tekač',
  'Cozinha da toca': 'Kuhinja v brlogu',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Vzemi sestavine iz zabojev, nasekljaj jih na deski, skuhaj na štedilniku in v pečici, da se ne prismodijo, jih naloži na krožnik in oddaj pri okencu. Vsi dobijo enaka naročila: zmaga, kdor v 3 minutah odda največ krožnikov.',
  'Pegar ou largar': 'Vzemi ali odloži',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'Ta igra potrebuje 3D grafiko, ki se na tej napravi ni odprla.',
  'Este prato não é o pedido.': 'Ta krožnik ni naročilo.',
  Kickflip: 'Kickflip',
  Grab: 'Grab',
  Manual: 'Manual',
  'Rolê do coelho': 'Zajčja vožnja',
  'Um minuto na pista de skate. Pule, gire, faça grind nos corrimãos e emende as manobras num combo: cada manobra a mais multiplica os pontos, mas cair perde o combo inteiro.': 'Ena minuta v skejt parku. Skači, vrti se, grindaj po ograjah in poveži trike v kombo: vsak dodatni trik pomnoži točke, a padec izgubi celoten kombo.',
  Pausar: 'Premor',
  'Caiu!': 'Padec!',
  'Melhor combo: {n}': 'Najboljši kombo: {n}',
  'Trânsito da toca': 'Promet pri brlogu',
  'Um minuto para soltar os carros do cruzamento sem deixar que batam. Fila cheia também custa pontos.': 'Ena minuta, da spuščaš avte čez križišče, ne da bi trčili. Polna vrsta tudi stane točke.',
  Liberar: 'Spusti',
  'Carrinhos da toca': 'Avtomobilčki pri brlogu',
  'Uma pista de carrinhos de brinquedo com quatro faixas: o carro segue a faixa sozinho, e você só acelera. Acelerou demais na curva, ele sai voando e perde tempo. No Solo, contra o relógio, os fantasmas dos amigos e robôs.': 'Steza za avtomobilčke igrače s štirimi pasovi: avto sam sledi svojemu pasu, ti samo pospešuješ. Če v ovinku preveč pospešiš, odleti s steze in izgubi čas. Solo: proti času, duhovom prijateljev in robotom.',
  'Acelerar': 'Pospeši',
  'Saiu da pista!': 'S steze!',
  'Saídas da pista: {n}': 'Izleti s steze: {n}',
  'Segure para acelerar e solte antes da curva: quando o carro treme, ele está no limite.': 'Drži za pospeševanje in spusti pred ovinkom: ko se avto trese, je na meji.',
