  // Saúde do servidor: ações da Hetzner e diagnóstico do host
  "Diagnóstico do host": "Diagnostika gostitelja",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Omejeni dnevniki Dockerja, SSH, logind in jedra iz zadnjih treh zagonov. Lahko vsebujejo naslove IP.",
  "Atualizar diagnóstico": "Osveži diagnostiko",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Posnetka še ni. Zajet bo ob naslednjem odprtju trezorja.",
  "Coletado em {data}": "Zajeto {data}",
  "Medido pela {nome}": "Izmeril {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "Iste številke kot na nadzorni plošči ponudnika. Vključuje disk, ki ga strežnik sam ne meri.",
  "Ações no servidor": "Dejanja na strežniku",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Zgodovina pri Hetznerju: vklop, izklop in ponovni zagon, z nadzorne plošče ali prek API-ja. Izpad brez dejanja tukaj ni bil sprožen po teh poteh.",
  "Nenhuma ação registrada.": "Ni zabeleženih dejanj.",
