  // O fundo da câmera (16/11/2026)
  'Fundo da câmera': "Ozadje kamere",
  'Desfocado': "Zamegli",
  'Desfoca, apaga ou troca o que aparece atrás de você. A imagem da câmera não sai do computador para isso.': "Zamegli, izbriše ali zamenja tisto, kar se vidi za tabo. Slika s kamere zaradi tega ne zapusti tvojega računalnika.",
  // A transmissão personalizada (16/11/2026)
  'Nativa': "Izvorna",
  'Resolução': "Ločljivost",
  'Quadros por segundo': "Sličice na sekundo",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Za takrat, ko se samodejna izbira zmoti: ločljivost in sličice ostanejo, kot jih izbereš, od začetka do konca prenosa.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Učinki za glas in kamero, ki nastanejo na tvojem računalniku, ne da bi karkoli poslali na strežnik.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Ječa v brlogu",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Skupaj prečkajte brlog gobjega kralja: sobe, polne živalic, skrinja s korenčkom, ki odleti in se vrne, gumbi, ki zahtevajo dva hkrati, in zaklenjena vrata. Od 1 do 4 ljudi.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Ring pri brlogu",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Boks refleksov proti trem računalniškim nasprotnikom. Beri napoved vsakega udarca, izmakni se ali blokiraj in udari v odprtino. Udarec, ko se rokavica zalesketa, napolni zvezdo močnega udarca.",
  'Esquivar': "Izmakni se",
  'Abaixar e defender': "Skloni se in blokiraj",
  'Socar': "Udari",
  'Soco forte': "Močan udarec",
  'Aperte os socos para levantar!': "Pritiskaj udarce, da vstaneš!",
  'Lutas vencidas: {n}': "Dobljene borbe: {n}",
  'Nocaute!': "Nokavt!",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Korenčkov komando",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Teci in streljaj z ekipo: metalec korenčkov meri v osem smeri, granata odpre pot, in kdor osvobodi zaprte zajčke, dobi okrepitev. Na koncu čaka zmaj: od 1 do 4 ljudi.",
  'Andar e mirar': "Premikaj se in meri",
  'Granada': "Granata",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Zvezdna pot",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Zajci v vesoljskih ladjah nad površjem planeta in v vesolju: streljaj, drži strel, da zakleneš tarčo, zavrti se, da odbiješ strele, in na razcepu izberi pot. Ekipa leti po isti poti, na koncu pa čaka šef.",
  'Pirueta': "Vrtenje",
  'Segure para travar a mira': "Drži za zaklep",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Vrtni fliper",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Fliper miza na zelenjavnem vrtu: drži vzmet, odbijaj se od zeljnih glav in podri tri korenčke, da zasveti zajčja luknja, ki spusti še eno kroglico. Tri kroglice, preveč tresenja pa zaklene mizo.",
  'Palhetas': "Loparja",
  'Mola': "Vzmet",
  'Sacudir': "Pretresi",
  'Bola salva!': "Kroglica rešena!",
  'Multibola!': "Več kroglic!",
  'Mesa travada!': "Miza zaklenjena!",
