  'Desafios de voo: asa-delta, mochila a jato e paraquedas. Passe pelos anéis e pouse no alvo, perto do centro e de leve.': 'Letalski izzivi: zmaj, raketni nahrbtnik in padalo. Preleti obroče in pristani na tarči, blizu središča in nežno.',
