  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Kratka potezna RPG: vsak upravlja enega junaka skupine. Izbirajte skupaj, združujte napade in premagajte grajskega zmaja.",
