  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Hodi po travnikih, s korenčkom se spoprijatelji z živalcami v visoki travi in sestavi ekipo do šestih. Premagaj izziv v modri hiši, v sobi pa se pomeri z ekipo prijatelja.",
