  "{nome} terminou uma Maravilha: derrube-a em 2 minutos!": "{nome} dokonča Čudo: poruši ga v 2 minutah!",
  "{nome} tirou dados iguais e joga de novo.": "{nome} vrže dvojček in igra znova.",
