  "1 contra 3": "1 proti 3",
  "2 contra 2": "2 proti 2",
  "A armadilha de {nome} disparou: quem sai junto?": "Past ({nome}) se je sprožila: kdo gre hkrati iz igre?",
  "A largada precisa de uma reta.": "Start potrebuje ravnino.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "Čudo ({nome}) je stalo 2 minuti.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Ista pozicija tretjič je remi, prav tako 20 potez samo z damami brez jemanja.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Ponoči poglej, koga so napadli volkodlaki. En napoj to osebo reši, drugi pa nekoga vrže iz igre; vsak velja enkrat.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "Igra se je med računalniki razšla in je bila končana.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "Kamen, ki konča potezo v zadnji vrsti, postane dama, ki gre po celi diagonali.",
  "A pista ainda não fecha a volta.": "Proga še ne zaključi kroga.",
  "A pista está curta demais.": "Proga je prekratka.",
  "A pista passa por cima dela mesma.": "Proga gre sama čez sebe.",
  "A pista precisa de mais peças.": "Proga potrebuje več delov.",
  "A turma age antes nas duas rodadas seguintes.": "Skupina ukrepa prej v naslednjih dveh krogih.",
  "A turma está decidindo.": "Skupina se odloča.",
  "A turma inteira leva bem menos dano nesta rodada.": "Vsa skupina v tem krogu dobi veliko manj škode.",
  "A turma recupera vida no fim de três rodadas.": "Skupina si na koncu treh krogov povrne življenje.",
