  "As pedras andam uma casa na diagonal, para a frente. Comer é obrigatório, também para trás, e vale o lance que come mais.": "Kamni gredo za eno polje diagonalno naprej. Jemanje je obvezno, tudi nazaj, in velja poteza, ki vzame največ.",
  "As regras do xadrez inteiras. Clique na peça e depois na casa: as casas que valem acendem.": "Celotna pravila šaha. Klikni figuro in nato polje: veljavna polja zasvetijo.",
