  // Os mini-games e as insígnias (19/11/2026)
  "{nome} terminou uma Maravilha: defenda-a por 2 minutos!": "{nome} dokonča Čudo: brani ga 2 minuti!",
  "{nome} terminou uma Maravilha.": "{nome} dokonča Čudo.",
  "A Maravilha da outra equipe ficou de pé por 2 minutos.": "Čudo druge ekipe je stalo 2 minuti.",
  "A Maravilha da sua equipe ficou de pé por 2 minutos.": "Čudo tvoje ekipe je stalo 2 minuti.",
