  "Duas equipes de dois. Os robôs completam os lugares que faltam.": "Dve ekipi po dva. Prosta mesta zapolnijo roboti.",
  "Gênero": "Spol",
  "Levadiça": "Dvižni most",
  'Nenhuma conversa ainda. Toque em alguém na lista de pessoas da comunidade e escolha "Enviar mensagem".': "Pogovorov še ni. Tapni nekoga na seznamu članov skupnosti in izberi „Pošlji sporočilo“.",
  "Varia": "Različno",
  "Vitória de {nomes}": "Zmaga: {nomes}",
  "Vocês derrubaram os dois centros da vila da outra equipe.": "Tvoja ekipa je porušila obe središči vasi druge ekipe.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Mesto, ki ga nihče ne kupi, gre na dražbo. Zastava mesta prinese denar, a mesto potem ne pobira najemnine.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Namig osvetli figuro, ki se premakne. Naloga z namigom ne prinese točk; na dirki odvzame 10 sekund.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Adut je vrednost za vrednostjo obrnjene karte in premaga vse. Med seboj: kara, pik, srce in križ, zap.",
  "A última nave de cada volta sai.": "Zadnja ladja v vsakem krogu izpade.",
  "Abaixar": "Skloni se",
  "Acertos em sequência: {n}": "Pravilno zapored: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Pomikaj se po kocki in kupi glavno mesto, kjer se ustaviš. Kdor se ustavi v mestu drugega, plača najemnino.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Vsaka vrstica, stolpec in blok 3 × 3 ima števila od 1 do 9, brez ponavljanja.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Vsi dobijo 3 karte. Roko vzame, kdor dobi 2 od 3 krogov.",
  "Campeonato": "Prvenstvo",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Pri 11 točkah par vidi karte in se odloči, ali igra roko enajstih. Zmaga, kdor doseže 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "S celo regijo zgradi do 4 stavbe: najemnina raste z vsako.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Z zvezdami močan udarec (★) porabi vse naenkrat in bolj boli.",
  "Dica": "Namig",
  "Dica: este problema não pontua": "Namig: ta naloga ne prinese točk",
  "Dica: tira 10 segundos": "Namig: odvzame 10 sekund",
  "Eliminação": "Izločanje",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Prisloni ploščico z isto številko k enemu od koncev na mizi.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Izberi polje in nato številko. Svinčnik zapisuje samo zate.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Izmakni se udarcu in udari takoj zatem: to je protinapad, in prinese zvezdo.",
  "Fora da corrida na volta {n}.": "Izpad iz dirke v krogu {n}.",
  "Força das cartas": "Moč kart",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Zmaga največje premoženje ob koncu krogov ali kdor ostane.",
  "Iniciante": "Začetnik",
  "Mestre": "Mojster",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "V Seriji vsak pravilen odgovor prinese težjo nalogo, prva napaka pa jo konča.",
  "O número pequeno no botão diz quantos ainda faltam.": "Majhna številka na gumbu pove, koliko jih še manjka.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Pet prog zapored proti računalniku, s točkami.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Napovej truco in roka velja 3. Kdor odgovarja, sprejme, zbeži ali dvigne na 6, 9 ali 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Kdor se znebi vseh ploščic, dobi točke iz rok drugih. Če je igra zaprta, jih dobi, kdor ima v roki najmanj točk.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Brez ploščice, ki ustreza, vleci. Ko ni česa vleči, poteza preide naprej.",
  "Sequência": "Serija",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Udari, ko se rokavica zalesketa: udarec se ustavi in dobiš zvezdo.",
  "Treino livre": "Prosti trening",
  // Os mini-games e as insígnias (19/11/2026)
  "{n} capitais": "Prestolnice: {n}",
  "{nome} aprendeu {golpe}!": "{nome} zna nov napad: {golpe}!",
  "{nome} deu {bicho} para você cuidar.": "{nome} ti zaupa v oskrbo: {bicho}.",
  "{nome} esqueceu {antigo} e aprendeu {golpe}.": "{nome}: namesto {antigo} zdaj zna {golpe}.",
  "{nome} parou com tudo valendo: +{n}": "{nome} kliče STOP in vsi odgovori veljajo: +{n}",
  "{nome} quer aprender {golpe}, mas já sabe 4 golpes.": "{nome} se želi naučiti {golpe}, a že zna 4 napade.",
  "{nome} tomou erva-doce e ficou bem.": "{nome} dobi komarček in je spet v redu.",
  "{nome} vai voltar para o mato. Tem certeza?": "{nome} se bo vrnil v travo. Zares?",
  "A geladeira pifou: pague {valor}.": "Hladilnik se je pokvaril: plačaj {valor}.",
  "A pedra não come para trás": "Kamen ne jemlje nazaj",
  "A restituição do imposto caiu na conta: receba {valor}.": "Vračilo davka je na računu: prejmi {valor}.",
  "A toca está vazia.": "Brlog je prazen.",
  "A turma fez uma vaquinha: cada um te dá {valor}.": "Skupina je zbrala denar: vsak ti da {valor}.",
  "Aceitar que não vale": "Sprejmi, da ne velja",
  "Achou um atalho: avance 5 casas.": "Bližnjica: pojdi 5 polj naprej.",
  "Alta temporada em {lugares}: os aluguéis dobram por uma rodada.": "Visoka sezona ({lugares}): najemnine se za en krog podvojijo.",
  "As duas diagonais também têm os números de 1 a 9.": "Tudi obe diagonali imata števila od 1 do 9.",
  "As escuras não fazem dois três abertos de uma vez": "Črni ne delajo dveh odprtih trojk hkrati",
  "As escuras não podem fazer dois três abertos de uma vez.": "Črni ne smejo narediti dveh odprtih trojk hkrati.",
  "Baixa temporada em {lugares}: os aluguéis caem pela metade por uma rodada.": "Nizka sezona ({lugares}): najemnine za en krog padejo na polovico.",
  "Batidas especiais: carroça e lá-e-ló valem o dobro": "Posebni zaključki: dvojček in kamen za oba konca štejeta dvojno",
  "Brasil inteiro": "Vsa Brazilija",
  "Captura: cercar duas pedras do outro tira as duas": "Zajem: obkolitev dveh nasprotnikovih kamnov odstrani oba",
  "Carroça!": "Dvojček!",
  "Cenoura dourada": "Zlati korenček",
  "Chá forte": "Močan čaj",
  "Chegou o IPTU: pague {valor} por cidade sua.": "Prišel je davek na nepremičnine: plačaj {valor} za vsako svoje mesto.",
  "Chuva de estrelas": "Zvezdni dež",
  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Z zajemom: dva nasprotnikova kamna med dvema tvojima sta odstranjena; pet zajemov tudi zmaga.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Z omejitvijo 3-3 črni ne smejo narediti dveh odprtih trojk hkrati.",
  "Com as batidas especiais, bater com carroça ou com a pedra que serve nas duas pontas vale o dobro; a carroça nas duas pontas, o quádruplo.": "S posebnimi zaključki zaključek z dvojčkom ali s kamnom, ki ustreza obema koncema, šteje dvojno; dvojček za oba konca štirikratno.",
  "Consulta no dentista: pague {valor}.": "Obisk pri zobozdravniku: plačaj {valor}.",
