  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Izžreba se skrivna žival, vsak pa ugiba druge. Vsak poskus pokaže, kaj se ujema s skrivno: razred, prehrana, kje živi in teža. Kdor ugane z manj poskusi, dobi več točk.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Izžreba se skrivni dinozaver, vsak pa ugiba druge. Vsak poskus pokaže, kaj se ujema s skrivnim: obdobje, prehrana, skupina, dolžina in kje so ga našli. Kdor ugane z manj poskusi, dobi več točk.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Izžreba se skrivni kemijski element, vsak pa ugiba druge. Vsak poskus pokaže, kaj se ujema s skrivnim: družina, agregatno stanje, perioda, skupina in vrstno število. Kdor ugane z manj poskusi, dobi več točk.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Izžreba se skrivna zvezna država Brazilije, vsak pa ugiba druge. Vsak poskus pokaže razdaljo in smer do skrivne, regijo, prebivalstvo, površino, obalo in mejo z drugo državo. Kdor ugane z manj poskusi, dobi več točk.",
