  "{pessoa} sai da comunidade e das chamadas dela na hora, e só volta se alguém que administra desbanir.": "{pessoa} takoj zapusti skupnost in njene klice in se vrne samo, če kdo od skrbnikov prepoved odpravi.",
  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "Skrbniki te skupnosti so tvojemu računu izrekli prepoved, zato vstop ni mogoč.",
  "Só quem administra a comunidade pode banir alguém.": "Prepoved lahko izreče samo, kdor upravlja skupnost.",
