  "Essa pessoa não está banida.": "Ta oseba nima prepovedi.",
  "Só quem administra a comunidade fixa mensagens.": "Sporočila pripenja samo, kdor upravlja skupnost.",
  "Só as mensagens do canal podem ser fixadas, não as de um tópico.": "Pripeti je mogoče samo sporočila kanala, ne pa sporočil iz niti.",
